import{_ as t,o as i,c as s,a3 as n}from"./chunks/framework.DMtjdCb-.js";const a="/help/assets/continue-watching.en.GP0RzkHs.png",o="/help/assets/potplayer-weekly.en.BVMI6FZ1.png",r="/help/assets/viewing-record.en.DdM_tLP-.png",w=JSON.parse('{"title":"6. Continue watching","description":"","frontmatter":{},"headers":[],"relativePath":"en/continue-watching.md","filePath":"en/continue-watching.md"}'),l={name:"en/continue-watching.md"};function h(d,e,c,p,g,u){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="_6-continue-watching" tabindex="-1">6. Continue watching <a class="header-anchor" href="#_6-continue-watching" aria-label="Permalink to &quot;6. Continue watching&quot;">​</a></h1><p>Continue watching combines subscribed TV titles with new episodes left to watch. Each title starts at its saved resume episode, includes that episode, and continues to the latest playable one.</p><h2 id="build-this-viewing-session" tabindex="-1">Build this viewing session <a class="header-anchor" href="#build-this-viewing-session" aria-label="Permalink to &quot;Build this viewing session&quot;">​</a></h2><ol><li>Open <strong>Release radar</strong> and choose a season.</li><li>Select <strong>Continue watching</strong> and wait for the episode list.</li><li>Check the titles you want. None are checked initially; selecting at least one enables the player buttons.</li><li>Drag each row by its handle to change the order. Adjust the episode range if needed.</li><li>Choose a player. The final playlist includes checked titles only, from top to bottom.</li></ol><p><img src="'+a+'" alt="Continue watching: select titles and drag them into order" loading="lazy"></p><p><strong>Expected result:</strong> the player&#39;s playlist contains the selected titles and episodes in your chosen order.</p><p><img src="'+o+'" alt="PotPlayer sidebar: multiple titles in one playlist" loading="lazy"></p><p>For example, A resumes at episode 3 and has episodes through 4; B resumes at 4 and has episodes through 5. With A first, the list contains A 3–4, then B 4–5. The next session is recalculated from the viewing records actually received.</p><h2 id="understand-the-pale-green-highlight" tabindex="-1">Understand the pale-green highlight <a class="header-anchor" href="#understand-the-pale-green-highlight" aria-label="Permalink to &quot;Understand the pale-green highlight&quot;">​</a></h2><p>Pale green means <strong>subscribed, with the latest episode not yet finished</strong>. Opening details or changing the resume episode to the latest episode keeps this highlight.</p><p>The latest episode is considered finished when any one of these applies:</p><ul><li>You choose <strong>Latest episode finished</strong>.</li><li>You save a resume episode greater than the current latest episode.</li><li>The PotPlayer extension reports at least <strong>90%</strong> progress through the latest episode.</li></ul><p>A new episode starts a new check. Paused, unsubscribed, and hidden titles are excluded from newly generated catch-up playlists; their viewing records remain saved.</p><h2 id="correct" tabindex="-1">Correct a viewing record <a class="header-anchor" href="#correct" aria-label="Permalink to &quot;Correct a viewing record {#correct}&quot;">​</a></h2><ol><li>Click the number in the radar&#39;s <strong>Watched</strong> column, or open the viewing record in title details.</li><li>Enter the episode to start from next time and, if needed, a precise position.</li><li>Choose <strong>Save</strong>. The radar and future playlists use the updated record.</li></ol><p><img src="'+r+'" alt="Viewing record: save, restart, or mark the latest episode finished" loading="lazy"></p><p><strong>Watch from the beginning</strong> resets the resume state. <strong>Latest episode finished</strong> explicitly confirms completion. Use <strong>Undo</strong> in the same window to restore the preceding record after a mistake.</p><p>Generating a playlist does not mark all its episodes watched. Media-access inference can be affected by player prefetching; precise extension feedback is more reliable.</p>',18)])])}const f=t(l,[["render",h]]);export{w as __pageData,f as default};
